import React from 'react';
import { FileText, Download, FileSpreadsheet, Calendar, Sparkles, CheckCircle2 } from 'lucide-react';

const ReportsPage = () => {
  const reports = [
    { title: 'Daily Factory OEE & Production Report', type: 'Daily Summary', date: '2026-07-31', size: '1.4 MB', fmt: 'PDF / CSV' },
    { title: 'AI Predictive RUL & Maintenance Briefing', type: 'AI Intelligence', date: '2026-07-30', size: '2.8 MB', fmt: 'PDF' },
    { title: 'Weekly Weaving Loom Energy Audit', type: 'Energy Consumption', date: '2026-07-28', size: '3.1 MB', fmt: 'CSV / Excel' },
    { title: 'Monthly Machine Downtime & Incident Summary', type: 'Monthly Analytics', date: '2026-07-01', size: '5.2 MB', fmt: 'PDF' },
  ];

  const triggerDownload = (title, format) => {
    const csvContent = 'data:text/csv;charset=utf-8,ReportTitle,Date,Status\n"' + title + '","2026-07-31","Generated"';
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `${title.replace(/\s+/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>📄 Operational Reports & Export Center</h1>
            <span className="badge badge-running" style={{ fontWeight: '800' }}>Automated Generation</span>
          </div>
          <p>Export Daily, Weekly, Monthly, and AI-Generated Performance Summaries</p>
        </div>

        <button className="btn btn-primary" onClick={() => triggerDownload('TexTwin_Executive_Report', 'CSV')}>
          <Download size={16} /> Generate Executive Summary
        </button>
      </div>

      {/* Reports Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '1.25rem', marginBottom: '1.75rem' }}>
        {reports.map((r, idx) => (
          <div key={idx} className="glass-card" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
            <div>
              <span className="badge badge-low" style={{ marginBottom: '0.75rem' }}>{r.type}</span>
              <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '4px' }}>{r.title}</h3>
              <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: '0.5rem', fontWeight: '600' }}>
                Generated: {r.date} • Format: {r.fmt}
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem', paddingTop: '0.85rem', borderTop: '1px solid var(--border-subtle)' }}>
              <span style={{ fontSize: '0.75rem', fontWeight: '700', color: 'var(--text-secondary)' }}>File Size: {r.size}</span>
              <button className="btn btn-secondary btn-sm" onClick={() => triggerDownload(r.title, 'CSV')}>
                <Download size={14} /> Download
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ReportsPage;
